package com.example.pacmantest;
import android.app.Activity;
import android.os.Bundle;
import android.content.Context;
import android.graphics.*;
import android.hardware.*;
import android.speech.tts.TextToSpeech;
import android.media.AudioManager;
import android.media.ToneGenerator;
import android.view.*;
import java.util.*;

public class MainActivity extends Activity implements SensorEventListener {
 SensorManager sensors; Sensor accel; Game game; TextToSpeech speech; ToneGenerator tones;
 float tiltX=0,tiltY=0,tiltZ=0,zeroX=0,zeroY=0,zeroZ=0; boolean calibrated=false; boolean sensorAvailable=false;
 @Override public void onCreate(Bundle b){super.onCreate(b); sensors=(SensorManager)getSystemService(SENSOR_SERVICE);accel=sensors.getDefaultSensor(Sensor.TYPE_ACCELEROMETER);sensorAvailable=accel!=null;tones=new ToneGenerator(AudioManager.STREAM_MUSIC,85);game=new Game(this);setContentView(game);speech=new TextToSpeech(this,status->{if(status==TextToSpeech.SUCCESS&&speech!=null){int lang=speech.setLanguage(new Locale("el","GR"));game.ttsReady=lang!=TextToSpeech.LANG_MISSING_DATA&&lang!=TextToSpeech.LANG_NOT_SUPPORTED;if(game.ttsReady)speech.speak("Βοήθεια! Έρχεται ο Μήτσος!",TextToSpeech.QUEUE_FLUSH,null,"start");}});}
 @Override protected void onResume(){super.onResume();if(accel!=null)sensors.registerListener(this,accel,SensorManager.SENSOR_DELAY_GAME);}
 @Override protected void onPause(){sensors.unregisterListener(this);super.onPause();}
 @Override protected void onDestroy(){if(speech!=null){speech.stop();speech.shutdown();}if(tones!=null)tones.release();super.onDestroy();}
 @Override public void onAccuracyChanged(Sensor s,int a){}
 @Override public void onSensorChanged(SensorEvent e){if(e.sensor.getType()!=Sensor.TYPE_ACCELEROMETER)return;tiltX=.8f*tiltX+.2f*e.values[0];tiltY=.8f*tiltY+.2f*e.values[1];tiltZ=.8f*tiltZ+.2f*e.values[2];if(!calibrated){zeroX=tiltX;zeroY=tiltY;zeroZ=tiltZ;calibrated=true;}}
 class Game extends View {
  final int W=15,H=19; final int[][] map=new int[H][W]; final boolean[][] pellets=new boolean[H][W]; final Paint p=new Paint(3); final Random rng=new Random(7); Bitmap face=null;
  float px=7,py=15; float heading=0; long[] ghostProtectedUntil={0,0,0,0,0}; int pelletsLeft=0; boolean ttsReady=false; float[] gx={2,12,7,3,11},gy={2,2,9,12,12}; int score=0,level=1,bestScore=0; long levelStarted=System.currentTimeMillis(); long last=0,lastVoice=0; float phase=0; boolean paused=false; int lives=3,fruitX=7,fruitY=9; boolean fruitActive=false, bossActive=false, recordCelebrated=false; float bossX=7,bossY=2; long turboUntil=0,lastHit=0,lastChomp=0,lastBossVoice=0; int fruitCounter=0; String message=""; long messageUntil=0;
  Game(Context c){super(c);setLayerType(View.LAYER_TYPE_SOFTWARE,null);int faceId=getResources().getIdentifier("mitsos_face","drawable",getPackageName());if(faceId!=0){try{face=BitmapFactory.decodeResource(getResources(),faceId);}catch(Exception ignored){face=null;}}if(face==null){try(java.io.InputStream in=getAssets().open("mitsos_face.b64");java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream()){byte[] buf=new byte[1024];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);byte[] bytes=android.util.Base64.decode(out.toByteArray(),android.util.Base64.DEFAULT);face=BitmapFactory.decodeByteArray(bytes,0,bytes.length);}catch(Exception ignored){face=null;}}bestScore=getContext().getSharedPreferences("mitsos_game",Context.MODE_PRIVATE).getInt("best_score",0);reset();}
  void say(String phrase){if(ttsReady&&speech!=null)speech.speak(phrase,TextToSpeech.QUEUE_FLUSH,null,"mitsos"+System.currentTimeMillis());}
  void notifyGame(String m){message=m;messageUntil=System.currentTimeMillis()+1800;}
  void reset(){bossActive=level%5==0;fruitActive=false;fruitCounter=0;levelStarted=System.currentTimeMillis();pelletsLeft=0;for(int y=0;y<H;y++)for(int x=0;x<W;x++){boolean wall=x==0||y==0||x==W-1||y==H-1||(x%4==0&&y%5!=2&&y%5!=3&&y>2&&y<H-3)||(y%6==0&&x%5!=2&&x%5!=3&&x>2&&x<W-3);map[y][x]=wall?1:0;pellets[y][x]=!wall;}map[15][7]=0;map[9][7]=0;map[2][2]=0;map[2][12]=0;pellets[15][7]=false;pellets[9][7]=false;pellets[2][2]=false;pellets[2][12]=false;px=7;py=15;heading=0;gx=new float[]{2,12,7,3,11};gy=new float[]{2,2,9,12,12};Arrays.fill(ghostProtectedUntil,0);boolean[][] seen=new boolean[H][W];ArrayDeque<int[]> q=new ArrayDeque<>();q.add(new int[]{7,15});seen[15][7]=true;while(!q.isEmpty()){int[] t=q.removeFirst();for(int[] d:new int[][]{{1,0},{-1,0},{0,1},{0,-1}}){int nx=t[0]+d[0],ny=t[1]+d[1];if(free(nx,ny)&&!seen[ny][nx]){seen[ny][nx]=true;q.addLast(new int[]{nx,ny});}}}for(int y=0;y<H;y++)for(int x=0;x<W;x++)if(!seen[y][x])pellets[y][x]=false;else if(pellets[y][x])pelletsLeft++;}
  void saveBest(){if(score>bestScore){if(!recordCelebrated&&score>=100){recordCelebrated=true;notifyGame("ΝΕΟ ΡΕΚΟΡ!");say("Μπράβο Μήτσο! Νέο ρεκόρ!");}bestScore=score;getContext().getSharedPreferences("mitsos_game",Context.MODE_PRIVATE).edit().putInt("best_score",bestScore).apply();}}
  boolean free(int x,int y){return x>=0&&x<W&&y>=0&&y<H&&map[y][x]==0;}
  void move(float dx,float dy){float nx=px+dx,ny=py+dy;int tileX=Math.round(px),tileY=Math.round(py);if(free(Math.round(nx),tileY))px=nx;if(free(Math.round(px),Math.round(ny)))py=ny;px=Math.max(.5f,Math.min(W-1.5f,px));py=Math.max(.5f,Math.min(H-1.5f,py));}
  void step(float dt){if(paused)return;phase+=dt*9;long now=System.currentTimeMillis();float dx=-(tiltX-zeroX),dy=-(tiltZ-zeroZ);if(Math.abs(dy)<.6f)dy=-(tiltY-zeroY);float dead=.38f;if(Math.abs(dx)<dead)dx=0;if(Math.abs(dy)<dead)dy=0;float mx=Math.max(-1,Math.min(1,dx/2.4f)),my=Math.max(-1,Math.min(1,dy/2.4f));if(Math.abs(mx)>Math.abs(my)&&Math.abs(mx)>.05f)heading=mx>0?0:180;else if(Math.abs(my)>.05f)heading=my>0?90:270;move(mx*dt*(now<turboUntil?11.5f:6.2f),my*dt*(now<turboUntil?11.5f:6.2f));
   int ix=Math.round(px),iy=Math.round(py);if(free(ix,iy)&&pellets[iy][ix]){pellets[iy][ix]=false;pelletsLeft--;score+=10;fruitCounter++;saveBest();if(tones!=null&&now-lastChomp>95){lastChomp=now;tones.startTone((score/10)%2==0?ToneGenerator.TONE_PROP_BEEP:ToneGenerator.TONE_PROP_BEEP2,55);}if(fruitCounter%18==0){fruitActive=true;fruitX=7;fruitY=9;if(!free(fruitX,fruitY)){fruitX=7;fruitY=15;}}}
   if(fruitActive&&Math.hypot(px-fruitX,py-fruitY)<.9f){fruitActive=false;score+=250;turboUntil=now+5500;saveBest();notifyGame("ΚΕΡΑΣΙΑ +250 / TURBO!");if(tones!=null)tones.startTone(ToneGenerator.TONE_PROP_ACK,250);say("Τούρμπο Μήτσος!");}
   if(bossActive){float dd=(float)Math.hypot(px-bossX,py-bossY);if(dd<1.05f&&now-lastHit>2200){lives--;lastHit=now;notifyGame("ΠΡΟΣΟΧΗ ΣΤΟ BOSS!");if(tones!=null)tones.startTone(ToneGenerator.TONE_PROP_NACK,350);if(lives<=0){lives=3;score=0;level=1;recordCelebrated=false;reset();say("Ωχ! Ο Μήτσος έχασε! Πάμε ξανά!");return;}px=7;py=15;}float bx=bossX,by=bossY;float vx=px-bx,vy=py-by;float norm=(float)Math.max(1,Math.hypot(vx,vy));float sx=bx+vx/norm*dt*1.2f,sy=by+vy/norm*dt*1.2f;if(free(Math.round(sx),Math.round(sy))){bossX=sx;bossY=sy;}if(now-lastBossVoice>11000){lastBossVoice=now;say("Ο μεγάλος αρχηγός έρχεται!");}}
   for(int i=0;i<gx.length;i++){float dist=(float)Math.hypot(px-gx[i],py-gy[i]);if(dist<.7f&&System.currentTimeMillis()>ghostProtectedUntil[i]){score+=100;saveBest();if(tones!=null)tones.startTone(ToneGenerator.TONE_PROP_ACK,130);ghostProtectedUntil[i]=System.currentTimeMillis()+2500;gx[i]=new float[]{2,12,7,3,11}[i];gy[i]=new float[]{2,2,9,12,12}[i];say(new String[]{"Ααα! Με έφαγε ο Μήτσος!","Μη με φας!","Μαμά μου!","Τρέξτε! Έρχεται ο Μήτσος!","Βοήθεια!"}[i]);continue;}float best=-999;int bx=0,by=0;for(int[] d:new int[][]{{1,0},{-1,0},{0,1},{0,-1}}){int nx=Math.round(gx[i])+d[0],ny=Math.round(gy[i])+d[1];if(!free(nx,ny))continue;float v=(float)Math.hypot(nx-px,ny-py)+rng.nextFloat()*.8f;if(v>best){best=v;bx=d[0];by=d[1];}}float speed=dt*(1.3f+level*.12f);float nextX=gx[i]+bx*speed,nextY=gy[i]+by*speed;if(free(Math.round(nextX),Math.round(nextY))){gx[i]=nextX;gy[i]=nextY;}
    if(dist<4&&System.currentTimeMillis()-lastVoice>9000&&ttsReady&&speech!=null){lastVoice=System.currentTimeMillis();say(new String[]{"Βοήθεια! Έρχεται ο Μήτσος!","Τρέξτε! Έρχεται ο Μήτσος!","Μη με φας!","Μαμά μου!","Σώστε με!"}[rng.nextInt(5)]);}
   }
   if(pelletsLeft==0){level++;reset();notifyGame(level%5==0?"BOSS LEVEL!":"ΕΠΙΠΕΔΟ "+level);}
  }
  void drawGhost3D(Canvas c,float x,float y,float radius,int color,boolean big){
   float bob=(float)Math.sin(phase*1.5f+x*.3f)*radius*.09f; y+=bob;
   p.setShader(null);p.setStyle(Paint.Style.FILL);
   p.setColor(Color.argb(115,0,0,0));c.drawOval(x-radius*.88f,y+radius*.82f,x+radius*.88f,y+radius*1.12f,p);
   Path body=new Path();body.moveTo(x-radius,y+radius*.58f);body.lineTo(x-radius,y);
   body.cubicTo(x-radius,y-radius*1.35f,x+radius,y-radius*1.35f,x+radius,y);
   body.lineTo(x+radius,y+radius*.7f);
   for(int k=3;k>=0;k--){float a=x-radius+(2*radius*k/4f);body.quadTo(a-radius*.24f,y+radius*(k%2==0?.95f:.5f),a-radius*.5f,y+radius*.68f);}
   body.close();
   int light=Color.rgb(Math.min(255,Color.red(color)+95),Math.min(255,Color.green(color)+95),Math.min(255,Color.blue(color)+95));
   int dark=Color.rgb((int)(Color.red(color)*.35f),(int)(Color.green(color)*.35f),(int)(Color.blue(color)*.35f));
   p.setShader(new RadialGradient(x-radius*.38f,y-radius*.56f,radius*1.8f,new int[]{Color.WHITE,light,color,dark},new float[]{0f,.23f,.57f,1f},Shader.TileMode.CLAMP));
   c.drawPath(body,p);p.setShader(null);
   p.setColor(Color.argb(95,255,255,255));c.drawOval(x-radius*.65f,y-radius*.76f,x-radius*.13f,y-radius*.38f,p);
   for(int e=-1;e<=1;e+=2){float ex=x+e*radius*.35f,ey=y-radius*.12f;p.setColor(Color.WHITE);c.drawOval(ex-radius*.28f,ey-radius*.33f,ex+radius*.28f,ey+radius*.32f,p);p.setColor(Color.rgb(22,45,94));c.drawCircle(ex+radius*.07f,ey+radius*.06f,radius*.14f,p);p.setColor(Color.BLACK);c.drawCircle(ex+radius*.09f,ey+radius*.06f,radius*.075f,p);p.setColor(Color.WHITE);c.drawCircle(ex+radius*.04f,ey-radius*.02f,radius*.045f,p);}
   if(big){p.setColor(Color.YELLOW);p.setTextSize(radius*.7f);p.setTextAlign(Paint.Align.CENTER);c.drawText("BOSS",x,y+radius*1.7f,p);p.setTextAlign(Paint.Align.LEFT);}
  }
  @Override protected void onDraw(Canvas c){long now=System.currentTimeMillis();float dt=last==0?0:Math.min(.045f,(now-last)/1000f);last=now;step(dt);super.onDraw(c);c.drawColor(Color.rgb(7,7,19));p.setShader(new LinearGradient(0,90,0,getHeight(),Color.rgb(12,17,44),Color.rgb(2,4,12),Shader.TileMode.CLAMP));c.drawRect(0,85,getWidth(),getHeight(),p);p.setShader(null);float cell=Math.max(1f,Math.min(getWidth()/(float)W,(getHeight()-110f)/H));float ox=(getWidth()-W*cell)/2,oy=90;
   p.setTextSize(Math.min(32f,Math.max(16f,getWidth()/13f)));p.setColor(Color.WHITE);c.drawText("ΜΗΤΣΟΣ  "+score+"   LEVEL "+level+"   ΖΩΕΣ: "+lives,16,46,p);p.setTextSize(Math.min(17f,Math.max(11f,getWidth()/25f)));c.drawText(sensorAvailable?"Πάνω: παύση | Πίστα: βαθμονόμηση":"Δεν βρέθηκε αισθητήρας κλίσης",16,72,p);p.setTextSize(15);c.drawText("Τελείες: "+pelletsLeft,Math.max(12,getWidth()-140),72,p);p.setTextSize(13);c.drawText("ΡΕΚΟΡ: "+bestScore,Math.max(12,getWidth()-120),Math.max(88,getHeight()-8),p);if(paused){p.setColor(Color.YELLOW);p.setTextSize(24);c.drawText("ΠΑΥΣΗ",Math.max(12,getWidth()/2-45),Math.max(120,getHeight()-15),p);}
   for(int y=0;y<H;y++)for(int x=0;x<W;x++){float cx=ox+(x+.5f)*cell,cy=oy+(y+.5f)*cell;if(map[y][x]==1){float l=ox+x*cell+1,t=oy+y*cell+1,r=l+cell-2,b=t+cell-2,depth=Math.max(2f,cell*.19f);p.setShader(null);p.setColor(Color.rgb(5,15,55));c.drawRoundRect(l+depth*.4f,t+depth*.7f,r,b+depth*.7f,5,5,p);p.setShader(new LinearGradient(l,t,r,b,new int[]{Color.rgb(90,195,255),Color.rgb(22,80,215),Color.rgb(8,24,100)},null,Shader.TileMode.CLAMP));c.drawRoundRect(l,t,r,b-depth*.15f,5,5,p);p.setShader(null);p.setColor(Color.rgb(115,225,255));p.setStrokeWidth(Math.max(1.3f,cell*.065f));c.drawLine(l+3,t+2,r-3,t+2,p);c.drawLine(l+2,t+3,l+2,b-depth*.45f,p);p.setColor(Color.rgb(5,17,68));c.drawLine(l+3,b-depth*.23f,r-2,b-depth*.23f,p);}else if(pellets[y][x]){p.setColor(Color.argb(70,255,196,90));c.drawCircle(cx,cy,cell*.19f,p);p.setColor(Color.rgb(255,235,170));c.drawCircle(cx,cy,cell*.09f,p);p.setColor(Color.WHITE);c.drawCircle(cx-cell*.025f,cy-cell*.025f,cell*.028f,p);}}
   if(fruitActive){p.setColor(Color.RED);c.drawCircle(ox+(fruitX+.3f)*cell,oy+(fruitY+.5f)*cell,cell*.21f,p);c.drawCircle(ox+(fruitX+.65f)*cell,oy+(fruitY+.5f)*cell,cell*.21f,p);p.setColor(Color.GREEN);c.drawLine(ox+(fruitX+.5f)*cell,oy+(fruitY+.3f)*cell,ox+(fruitX+.55f)*cell,oy+(fruitY+.08f)*cell,p);}
   if(bossActive){float bx=ox+(bossX+.5f)*cell,by=oy+(bossY+.5f)*cell;drawGhost3D(c,bx,by,cell*.67f,Color.rgb(165,40,235),true);}
   for(int i=0;i<gx.length;i++){float x=ox+(gx[i]+.5f)*cell,y=oy+(gy[i]+.5f)*cell;drawGhost3D(c,x,y,cell*.43f,new int[]{Color.RED,Color.CYAN,Color.MAGENTA,Color.GREEN,Color.YELLOW}[i],false);}
   float x=ox+(px+.5f)*cell,y=oy+(py+.5f)*cell;float mouth=(float)(15+30*Math.abs(Math.sin(phase)));p.setColor(Color.YELLOW);if(face!=null){c.save();Path circle=new Path();circle.addCircle(x,y,cell*.49f,Path.Direction.CW);c.clipPath(circle);p.setColor(Color.WHITE);c.drawBitmap(face,null,new RectF(x-cell*.49f,y-cell*.49f,x+cell*.49f,y+cell*.49f),p);c.restore();p.setShader(new LinearGradient(x-cell*.48f,y-cell*.48f,x+cell*.48f,y+cell*.48f,new int[]{Color.argb(105,255,255,255),Color.TRANSPARENT,Color.argb(100,0,0,0)},null,Shader.TileMode.CLAMP));c.drawCircle(x,y,cell*.49f,p);p.setShader(null);p.setColor(Color.rgb(7,7,19));c.drawArc(x-cell*.44f,y-cell*.44f,x+cell*.44f,y+cell*.44f,heading-mouth,2*mouth,true,p);}else{c.drawArc(x-cell*.42f,y-cell*.42f,x+cell*.42f,y+cell*.42f,heading+mouth,360-2*mouth,true,p);p.setColor(Color.BLACK);c.drawCircle(x+cell*.04f,y-cell*.19f,cell*.055f,p);}
   if(now<turboUntil){p.setColor(Color.YELLOW);p.setTextSize(18);c.drawText("TURBO!",Math.max(12,getWidth()-90),45,p);}if(now<messageUntil){p.setColor(Color.YELLOW);p.setTextSize(20);c.drawText(message,15,Math.max(120,getHeight()-35),p);}
   if(System.currentTimeMillis()-levelStarted<1800){p.setColor(Color.YELLOW);p.setTextSize(Math.min(24f,Math.max(14f,getWidth()/17f)));c.drawText("ΕΠΙΠΕΔΟ "+level,Math.max(12,getWidth()/2-70),Math.max(120,getHeight()-20),p);}postInvalidateDelayed(16);
  }
  @Override public boolean onTouchEvent(android.view.MotionEvent e){if(e.getAction()==MotionEvent.ACTION_UP){if(e.getY()<85){paused=!paused;last=System.currentTimeMillis();invalidate();}else if(sensorAvailable){zeroX=tiltX;zeroY=tiltY;zeroZ=tiltZ;calibrated=true;}return true;}return true;}
 }
}